module TopModule(
    input  [15:0] a,
    input  [15:0] b,
    input  [15:0] c,
    input  [15:0] d,
    input  [15:0] e,
    input  [15:0] f,
    input  [15:0] g,
    input  [15:0] h,
    input  [15:0] i,
    input  [ 3:0] sel,
    output [15:0] out
);
    wire [15:0] and0 = a & (~sel[0]) & (~sel[1]) & (~sel[2]) & (~sel[3]);
    wire [15:0] and1 = b & sel[0] & (~sel[1]) & (~sel[2]) & (~sel[3]);
    wire [15:0] and2 = c & (~sel[0]) & sel[1] & (~sel[2]) & (~sel[3]);
    wire [15:0] and3 = d & sel[0] & sel[1] & (~sel[2]) & (~sel[3]);
    wire [15:0] and4 = e & (~sel[0]) & (~sel[1]) & sel[2] & (~sel[3]);
    wire [15:0] and5 = f & sel[0] & (~sel[1]) & sel[2] & (~sel[3]);
    wire [15:0] and6 = g & (~sel[0]) & sel[1] & sel[2] & (~sel[3]);
    wire [15:0] and7 = h & sel[0] & sel[1] & sel[2] & (~sel[3]);
    wire [15:0] and8 = i & (~sel[0]) & (~sel[1]) & (~sel[2]) & sel[3];
    wire [15:0] out_onehot = and0 | and1 | and2 | and3 | and4 | and5 | and6 | and7 | and8;
    assign out = out_onehot;
endmodule

